Assume `uint8_t` is 8 bits and `int` is 32 bits. What does this print?

```c
#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint8_t a = 0xCA, b = 0x6C;
    printf("%02X %02X %02X %02X\n", (unsigned)(a & b),
           (unsigned)(a | b), (unsigned)(a ^ b),
           (unsigned)(uint8_t)~a);
}
```

Assume a 32-bit two's complement `int`. What does this print?

```c
#include <stdio.h>
int main(void) {
    int a = 1, b = 2;
    printf("%d %d %d %d\n", a & b, a && b, !a, ~a);
}
```

Assume `uint8_t` is 8 bits and `int` is 32 bits. What does this print?

```c
#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint8_t a = 200, b = 100;
    uint8_t s = a + b;
    int carry = s < a;
    printf("%u %d\n", (unsigned)s, carry);
}
```

A **shift register** is a chain of flip-flops in which every bit moves one place along at each clock edge while a new bit enters at one end. Assume `uint8_t` is 8 bits. This C model clocks in the bits 1, 0, 1, 1 in that order. What does it print?

```c
#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint8_t sr = 0;
    int in[] = {1, 0, 1, 1};
    for (int i = 0; i < 4; i++)
        sr = (uint8_t)(((sr << 1) | in[i]) & 0x0F);
    printf("%X\n", (unsigned)sr);
}
```

A turnstile FSM starts `LOCKED`. Event `c` is a coin (unlocks it) and `p` is a push (locks it); any other event changes nothing. Assume a 32-bit `int` and that enum constants count from 0. What does this print for the events `cppcc`?

```c
#include <stdio.h>
typedef enum { LOCKED, UNLOCKED } State;
static State step(State s, char e) {
    switch (s) {
    case LOCKED:   return e == 'c' ? UNLOCKED : LOCKED;
    case UNLOCKED: return e == 'p' ? LOCKED : UNLOCKED;
    }
    return s;
}
int main(void) {
    State s = LOCKED;
    for (const char *p = "cppcc"; *p; p++) s = step(s, *p);
    printf("%d\n", s);
}
```

A turnstile should unlock on a coin, lock on a push and otherwise stay put, so after COIN, COIN it must be `UNLOCKED`. Assume a 32-bit `int`. This table-driven version prints 0 instead of 1. Which table entry is wrong, and what should it be?

```c
#include <stdio.h>
typedef enum { LOCKED, UNLOCKED } State;
typedef enum { COIN, PUSH } Event;
static const State next[2][2] = {   /* [state][event] */
    { UNLOCKED, LOCKED },           /* from LOCKED   */
    { LOCKED,   LOCKED },           /* from UNLOCKED */
};
int main(void) {
    State s = LOCKED;
    s = next[s][COIN];
    s = next[s][COIN];
    printf("%d\n", s);
}
```

This C model of the 101 detector (S0: no progress, S1: last bit 1, S2: last two bits 10) reads the string `10101101`. Assume ASCII. What does it print?

```c
#include <stdio.h>
typedef enum { S0, S1, S2 } State;
int main(void) {
    State s = S0;
    int hits = 0;
    for (const char *p = "10101101"; *p; p++) {
        int bit = *p - '0';
        switch (s) {
        case S0: s = bit ? S1 : S0; break;
        case S1: s = bit ? S1 : S2; break;
        case S2: hits += bit; s = bit ? S1 : S0; break;
        }
    }
    printf("%d\n", hits);
}
```

In **event-driven firmware**, code runs only when something happens (a button press, a timer tick), instead of waiting in a delay loop. Here `on_event()` is called once per event. The events are COIN then PUSH, so `passes` should end at 1. Assume a 32-bit `int`. What does this print, and what is the one-word fix?

```c
#include <stdio.h>
typedef enum { LOCKED, UNLOCKED } State;
typedef enum { COIN, PUSH } Event;
static int passes = 0;
static void on_event(Event e) {
    State s = LOCKED;
    if (s == LOCKED && e == COIN) s = UNLOCKED;
    else if (s == UNLOCKED && e == PUSH) { passes++; s = LOCKED; }
}
int main(void) {
    on_event(COIN);
    on_event(PUSH);
    printf("%d\n", passes);
}
```
